"""Readable report from the frozen analysis, without refitting."""
import json,sys
from pathlib import Path
folder=Path(sys.argv[1]);a=json.loads((folder/'analysis.json').read_text());manifest=json.loads((folder/'manifest.json').read_text())
names={'no_on_target_10':'нет ударов в створ за 10 минут','shots_10_le_3':'не более 3 ударов за 10 минут','low_threat':'не более 1 в створ и 3 ударов за 10 минут','xg_10_le_015':'xG последних 10 минут <=0,15','on_target_decay':'снижение попаданий в створ с 2+ до 0–1','attack_decay':'опасные атаки снизились минимум вдвое','no_goal_10':'без голов 10 минут','quick_goals_then_pause':'2+ гола за 20 минут, затем пауза','ht_3plus':'3+ гола в первом тайме','lead_2plus':'преимущество 2+ гола','draw':'ничья','goals_2plus':'уже 2+ гола','score_0_0':'счёт 0:0','profile_low':'голевой профиль <=85% нормы лиги','profile_high':'голевой профиль >=115% нормы лиги','profile_both_under_25':'средний тотал обеих команд <=2,5','overconversion':'голов на 1,5+ больше xG','red_card':'есть удаление'}
def pct(v):return 'нет данных' if v is None else f'{100*v:.1f}%'
lines=['# Историческое исследование ТМ', '', 'Версия: tm-research-v1. Это поиск кандидатов, не активная live-стратегия.','',
'## Покрытие','',f"Завершённых матчей в целевой выборке: {a['coverage'].get('targets',0)}. С пригодными признаками: {a['coverage'].get('feature_matches',0)}. С хотя бы одной допустимой исторической ценой: {a['coverage'].get('quoted_matches',0)}.",'',
f"Матчи по частям: {a['splits']}. Проверено комбинаций: {a['research']['tested_rules']}; на валидацию передано не более 20, на финальную проверку не более пяти.",'',
'## Финальная проверка','', '| Условие | Минута | Не более дополнительных голов | Поиск N / доля | Валидация N / доля | Проверка N / доля | Изменение к сопоставимому контролю | p Холма |', '|---|---:|---:|---|---|---|---|---|']
for r in a['research']['finalists']:
    t=r['test'];lines.append('| '+' + '.join(names[x] for x in r['flags'])+f" | {r['minute']} | {r['target']} | {r['train']['n']} / {pct(r['train']['rate'])} | {r['validation']['n']} / {pct(r['validation']['rate'])} | {t['n']} / {pct(t['rate'])} | {pct(t['matched_lift'])} | {r.get('holm_p','нет данных')} |")
if not a['research']['finalists']:lines+=['','Ни одна гипотеза не прошла заранее заданные условия передачи на финальную проверку. Это не доказательство отсутствия эффекта.']
lines+=['','## Условный финансовый результат на проверочной части','', '| Условие | Минута | С ценой N | Средний коэффициент ТМ | Условный ROI |', '|---|---:|---:|---:|---:|']
for r in a['research']['finalists']:
    t=r['test'];lines.append('| '+' + '.join(names[x] for x in r['flags'])+f" | {r['minute']} | {t['priced_n']} | {t['mean_price']} | {pct(t['roi'])} |")
lines+=['','Финансовый результат относится к основной исторической линии Events, а спортивный исход - к указанному числу дополнительных голов: это разные показатели. ROI посчитан только для строк с допустимой ценой, одинаковой единицей, включая возвраты и четвертные исходы. Реальное исполнение и наличие цены в Олимпе не проверены. Пять кандидатов могут перекрываться; их объёмы и результаты нельзя складывать.','',
'## Ограничения','',
'Один временной контроль, две лиги, ограниченная история. Поиск условий на обучающей части не доказывает устойчивого преимущества. Тестовые p-значения скорректированы по Холму среди финалистов, интервалы долей описательные. Зависимость матчей одних команд и режимные изменения сезона могут уменьшать эффективную выборку. Исторические ряды могут содержать исправления провайдера; проверена отсечка времени публикации точек и согласованность итоговых счётчиков. Нет смешения с отбором, дневником и исключениями ТБ.','',
'Все исходники, запрос, первичные ответы, признаки и analysis.json находятся рядом. Правила live ТМ не активированы.']
(folder/'Результаты исследования.md').write_text('\n'.join(lines)+'\n')
print('\n'.join(lines))
